245	export function runCommand(
246		command,
247		args,
248		cwd,
249		{
250			timeout = DEFAULT_COMMAND_TIMEOUT_MS,
251			killSignal = DEFAULT_COMMAND_KILL_SIGNAL,
252		} = {},
253	) {
254		const commandTimeout =
255			Number.isFinite(timeout) && timeout > 0
256				? Math.floor(timeout)
257				: DEFAULT_COMMAND_TIMEOUT_MS;
258		const displayCommand = formatCommand(command, args);
259	
260		return new Promise((resolvePromise, reject) => {
261			let output = "";
262			let timedOut = false;
263			let settled = false;
264			let timeoutHandle;
265			let gracePeriodHandle;
266	
267			const finish = (callback) => {
268				if (settled) return;
269				settled = true;
270				if (timeoutHandle) clearTimeout(timeoutHandle);
271				if (gracePeriodHandle) clearTimeout(gracePeriodHandle);
272				callback();
273			};
274			const rejectWithMessage = (status, cause) => {
275				finish(() =>
276					reject(
277						new Error(
278							[`${displayCommand} failed: ${status}`, output.trim()]
279								.filter(Boolean)
280								.join("\n"),
281							{ cause },
282						),
283					),
284				);
285			};
286	
287			let child;
288			try {
289				child = spawn(command, args, {
290					cwd,
291					stdio: ["ignore", "pipe", "pipe"],
292					shell: false,
293					timeout: commandTimeout,
294					killSignal,
295				});
296			} catch (error) {
297				rejectWithMessage(
298					`could not start: ${error instanceof Error ? error.message : String(error)}`,
299					error,
300				);
301				return;
302			}
303	
304			timeoutHandle = setTimeout(
305				() => {
306					if (child.exitCode === null && child.signalCode === null) {
307						timedOut = true;
308						child.kill(killSignal);
309	
310						if (killSignal !== "SIGKILL") {
311							gracePeriodHandle = setTimeout(() => {
312								if (child.exitCode === null && child.signalCode === null) {
313									child.kill("SIGKILL");
314								}
315							}, SIGKILL_GRACE_PERIOD_MS);
316						}
317					}
318				},
319				Math.max(1, commandTimeout - 1),
320			);
321			child.stdout.on("data", (chunk) => {
322				output += chunk;
323			});
324			child.stderr.on("data", (chunk) => {
325				output += chunk;
326			});
327			child.once("error", (error) => {
328				const code = error?.code ? ` (${error.code})` : "";
329				rejectWithMessage(`could not start${code}: ${error.message}`, error);
330			});
331			child.once("close", (code, signal) => {
332				if (timedOut) {
333					rejectWithMessage(
334						`timed out after ${commandTimeout}ms; sent ${String(killSignal)}`,
335					);
336					return;
337				}
338				if (code === 0) {
339					finish(resolvePromise);
340					return;
341				}
342				rejectWithMessage(
343					signal ? `terminated by signal ${signal}` : `exited with code ${code}`,
344				);
345			});
346		});
347	}
